// The design's icons: Lucide (lucide-static 0.460.0, ISC license), drawn from their SVG path data
// (LucideData.swift, generated by scripts/gen-icons.py) the way Lucide draws them: a 24 x 24
// box, stroked at width 2 with round caps and joins, in the current foreground style. A shape,
// not an image, so it renders the same in the window and in the headless renders.

import SwiftUI

struct LucideIcon: View {
  let name: String
  var size: CGFloat = 16
  // Lucide's stroke width, in its 24-unit box
  var weight: CGFloat = 2

  var body: some View {
    LucideShape(name: name)
      .stroke(style: StrokeStyle(lineWidth: weight * size / 24, lineCap: .round, lineJoin: .round))
      .frame(width: size, height: size)
      .accessibilityHidden(true)
  }
}

struct LucideShape: Shape {
  let name: String

  func path(in rect: CGRect) -> Path {
    let base = LucideShape.cached(name)
    let s = min(rect.width, rect.height) / 24
    return base.applying(CGAffineTransform(a: s, b: 0, c: 0, d: s, tx: rect.minX, ty: rect.minY))
  }

  nonisolated(unsafe) private static var cache: [String: Path] = [:]
  private static let lock = NSLock()

  static func cached(_ name: String) -> Path {
    lock.lock(); defer { lock.unlock() }
    if let p = cache[name] { return p }
    var path = Path()
    for d in LucideData.paths[name] ?? [] { SVGPath.append(d, to: &path) }
    cache[name] = path
    return path
  }
}

// SVG path data (M L H V C S Q T A Z, absolute and relative) into a SwiftUI Path.
enum SVGPath {
  static func append(_ d: String, to path: inout Path) {
    var t = Tokens(Array(d.utf8))
    var cur = CGPoint.zero, start = CGPoint.zero
    var lastCtrl: CGPoint?, lastQuad: CGPoint?
    var cmd: UInt8 = 0
    while let c = t.nextCommand(current: cmd) {
      cmd = c
      let rel = c >= 97
      let o = rel ? cur : .zero
      switch c | 0x20 {
      case UInt8(ascii: "m"):
        guard let p = t.point() else { return }
        cur = CGPoint(x: o.x + p.x, y: o.y + p.y); start = cur
        path.move(to: cur)
        // further pairs are line-tos
        cmd = rel ? UInt8(ascii: "l") : UInt8(ascii: "L")
        lastCtrl = nil; lastQuad = nil
      case UInt8(ascii: "l"):
        guard let p = t.point() else { return }
        cur = CGPoint(x: o.x + p.x, y: o.y + p.y); path.addLine(to: cur)
        lastCtrl = nil; lastQuad = nil
      case UInt8(ascii: "h"):
        guard let x = t.number() else { return }
        cur = CGPoint(x: (rel ? cur.x : 0) + x, y: cur.y); path.addLine(to: cur)
        lastCtrl = nil; lastQuad = nil
      case UInt8(ascii: "v"):
        guard let y = t.number() else { return }
        cur = CGPoint(x: cur.x, y: (rel ? cur.y : 0) + y); path.addLine(to: cur)
        lastCtrl = nil; lastQuad = nil
      case UInt8(ascii: "c"):
        guard let a = t.point(), let b = t.point(), let p = t.point() else { return }
        let c1 = CGPoint(x: o.x + a.x, y: o.y + a.y), c2 = CGPoint(x: o.x + b.x, y: o.y + b.y)
        cur = CGPoint(x: o.x + p.x, y: o.y + p.y)
        path.addCurve(to: cur, control1: c1, control2: c2)
        lastCtrl = c2; lastQuad = nil
      case UInt8(ascii: "s"):
        guard let b = t.point(), let p = t.point() else { return }
        let c1 = lastCtrl.map { CGPoint(x: 2 * cur.x - $0.x, y: 2 * cur.y - $0.y) } ?? cur
        let c2 = CGPoint(x: o.x + b.x, y: o.y + b.y)
        cur = CGPoint(x: o.x + p.x, y: o.y + p.y)
        path.addCurve(to: cur, control1: c1, control2: c2)
        lastCtrl = c2; lastQuad = nil
      case UInt8(ascii: "q"):
        guard let a = t.point(), let p = t.point() else { return }
        let q = CGPoint(x: o.x + a.x, y: o.y + a.y)
        cur = CGPoint(x: o.x + p.x, y: o.y + p.y)
        path.addQuadCurve(to: cur, control: q)
        lastQuad = q; lastCtrl = nil
      case UInt8(ascii: "t"):
        guard let p = t.point() else { return }
        let q = lastQuad.map { CGPoint(x: 2 * cur.x - $0.x, y: 2 * cur.y - $0.y) } ?? cur
        cur = CGPoint(x: o.x + p.x, y: o.y + p.y)
        path.addQuadCurve(to: cur, control: q)
        lastQuad = q; lastCtrl = nil
      case UInt8(ascii: "a"):
        guard let rx = t.number(), let ry = t.number(), let rot = t.number(),
              let large = t.flag(), let sweep = t.flag(), let p = t.point() else { return }
        let end = CGPoint(x: o.x + p.x, y: o.y + p.y)
        arc(&path, from: cur, to: end, rx: rx, ry: ry, rotation: rot, large: large, sweep: sweep)
        cur = end
        lastCtrl = nil; lastQuad = nil
      case UInt8(ascii: "z"):
        path.closeSubpath(); cur = start
        lastCtrl = nil; lastQuad = nil
      default:
        return
      }
    }
  }

  // The SVG endpoint arc as cubic Béziers (SVG 1.1, F.6.5 and F.6.6).
  static func arc(_ path: inout Path, from p0: CGPoint, to p1: CGPoint, rx rxIn: CGFloat, ry ryIn: CGFloat,
                  rotation: CGFloat, large: Bool, sweep: Bool) {
    var rx = abs(rxIn), ry = abs(ryIn)
    if rx == 0 || ry == 0 || p0 == p1 { path.addLine(to: p1); return }
    let phi = rotation * .pi / 180, cp = cos(phi), sp = sin(phi)
    let dx = (p0.x - p1.x) / 2, dy = (p0.y - p1.y) / 2
    let x1 = cp * dx + sp * dy, y1 = -sp * dx + cp * dy
    let lambda = (x1 * x1) / (rx * rx) + (y1 * y1) / (ry * ry)
    if lambda > 1 { rx *= sqrt(lambda); ry *= sqrt(lambda) }
    let num = rx * rx * ry * ry - rx * rx * y1 * y1 - ry * ry * x1 * x1
    let den = rx * rx * y1 * y1 + ry * ry * x1 * x1
    var k = sqrt(max(0, num / den))
    if large == sweep { k = -k }
    let cxp = k * rx * y1 / ry, cyp = -k * ry * x1 / rx
    let cx = cp * cxp - sp * cyp + (p0.x + p1.x) / 2
    let cy = sp * cxp + cp * cyp + (p0.y + p1.y) / 2
    func angle(_ ux: CGFloat, _ uy: CGFloat, _ vx: CGFloat, _ vy: CGFloat) -> CGFloat {
      let a = atan2(ux * vy - uy * vx, ux * vx + uy * vy)
      return a
    }
    let t1 = angle(1, 0, (x1 - cxp) / rx, (y1 - cyp) / ry)
    var dt = angle((x1 - cxp) / rx, (y1 - cyp) / ry, (-x1 - cxp) / rx, (-y1 - cyp) / ry)
    if !sweep && dt > 0 { dt -= 2 * .pi } else if sweep && dt < 0 { dt += 2 * .pi }
    let segments = max(1, Int(ceil(abs(dt) / (.pi / 2))))
    let delta = dt / CGFloat(segments)
    let alpha = 4.0 / 3.0 * tan(delta / 4)
    var t = t1
    func pt(_ a: CGFloat) -> CGPoint {
      CGPoint(x: cx + rx * cos(a) * cp - ry * sin(a) * sp, y: cy + rx * cos(a) * sp + ry * sin(a) * cp)
    }
    func deriv(_ a: CGFloat) -> CGPoint {
      CGPoint(x: -rx * sin(a) * cp - ry * cos(a) * sp, y: -rx * sin(a) * sp + ry * cos(a) * cp)
    }
    for i in 0..<segments {
      let t2 = t + delta
      let a = pt(t), b = i == segments - 1 ? p1 : pt(t2)
      let da = deriv(t), db = deriv(t2)
      path.addCurve(to: b, control1: CGPoint(x: a.x + alpha * da.x, y: a.y + alpha * da.y),
                    control2: CGPoint(x: b.x - alpha * db.x, y: b.y - alpha * db.y))
      t = t2
    }
  }

  struct Tokens {
    let s: [UInt8]
    var i = 0
    init(_ s: [UInt8]) { self.s = s }

    mutating func skip() {
      while i < s.count, s[i] == 32 || s[i] == 44 || s[i] == 10 || s[i] == 9 || s[i] == 13 { i += 1 }
    }

    // the next command letter, or the current one repeated when numbers follow
    mutating func nextCommand(current: UInt8) -> UInt8? {
      skip()
      guard i < s.count else { return nil }
      let c = s[i]
      if (c >= 65 && c <= 90) || (c >= 97 && c <= 122) { i += 1; return c }
      return current == 0 ? nil : current
    }

    mutating func number() -> CGFloat? {
      skip()
      let begin = i
      if i < s.count, s[i] == 45 || s[i] == 43 { i += 1 }
      var dot = false, digits = false
      while i < s.count {
        let c = s[i]
        if c >= 48 && c <= 57 { digits = true; i += 1 }
        else if c == 46 && !dot { dot = true; i += 1 }
        else if (c == 101 || c == 69) && digits {
          i += 1
          if i < s.count, s[i] == 45 || s[i] == 43 { i += 1 }
        } else { break }
      }
      guard digits, let v = Double(String(decoding: s[begin..<i], as: UTF8.self)) else { i = begin; return nil }
      return CGFloat(v)
    }

    // an arc flag: one character, 0 or 1, possibly without a separator after it
    mutating func flag() -> Bool? {
      skip()
      guard i < s.count, s[i] == 48 || s[i] == 49 else { return nil }
      defer { i += 1 }
      return s[i] == 49
    }

    mutating func point() -> CGPoint? {
      guard let x = number(), let y = number() else { return nil }
      return CGPoint(x: x, y: y)
    }
  }
}
